const nodemailer = require('nodemailer');

const TO = 'sangnchr@gmail.com';

const transporter = nodemailer.createTransport({
  host: 'smtp.gmail.com',
  port: 465,
  secure: true,
  auth: {
    user: 'sangnchr@gmail.com',
    pass: process.env.GMAIL_PASS,
  },
});

function send(str) {
  return transporter.sendMail({
    from: TO,
    to: TO,
    subject: 'm0603 send()',
    text: str,
  });
}

module.exports = { send };

